using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using Calculator.Engine.UnitConversion;
using Xunit;

namespace Calculator.Engine.Tests;

/// <summary>
/// Accuracy of the unit converter. Three layers:
/// 1. every conversion factor against its exact reference definition (UnitReferenceData.g.cs, generated by tools/check_units.py);
/// 2. internal consistency of the whole table (A to B times B to A is 1);
/// 3. what the user really sees on the screen, for well known conversions, including under other machine cultures.
/// </summary>
public class ConverterAccuracyTests
{
    private sealed class Callback : IUnitConverterVMCallback
    {
        public string From { get; private set; } = string.Empty;

        public string To { get; private set; } = string.Empty;

        public void DisplayCallback(string from, string to)
        {
            From = from;
            To = to;
        }

        public void SuggestedValueCallback(List<(string Value, Unit Unit)> suggestedValues)
        {
        }

        public void MaxDigitsReached()
        {
        }
    }

    public static IEnumerable<object[]> Factors() => UnitReferenceData.Factors();

    private static UnitConverterDataLoader LoadData()
    {
        var loader = new UnitConverterDataLoader(key => key, "FR");
        loader.LoadData();
        return loader;
    }

    /// <summary>Types <paramref name="digits"/> in the converter and returns what the "to" field shows.</summary>
    private static string Convert(ConverterCategory category, string from, string to, string digits)
    {
        var converter = new UnitConverter(new UnitConverterDataLoader(key => key, "FR"));
        converter.Initialize();
        var callback = new Callback();
        converter.SetViewModelCallback(callback);

        Category cat = converter.GetCategories().First(c => c.Id == (int)category);
        (List<Unit> units, Unit _, Unit _) = converter.SetCurrentCategory(cat);
        converter.SetCurrentUnitTypes(units.First(u => u.Name == from), units.First(u => u.Name == to));
        foreach (char ch in digits)
        {
            converter.SendCommand(ch == '.' ? UnitConversionCommand.Decimal : (UnitConversionCommand)(ch - '0'));
        }

        return callback.To;
    }

    // ---- 1. every factor against its exact definition ----------------------------------------------------------

    [Theory]
    [MemberData(nameof(Factors))]
    public void Conversion_factor_matches_the_reference_definition(ConverterCategory category, string unitKey, string baseKey, double expected)
    {
        UnitConverterDataLoader loader = LoadData();
        Category cat = loader.GetOrderedCategories().First(c => c.Id == (int)category);
        List<Unit> units = loader.GetOrderedUnits(cat);
        Unit unit = units.First(u => u.Name == unitKey);
        Unit baseUnit = units.First(u => u.Name == baseKey);

        double actual = loader.LoadOrderedRatios(unit)[baseUnit].Ratio;
        double relativeError = Math.Abs(actual - expected) / expected;

        Assert.True(
            relativeError < 1e-9,
            $"1 {unitKey} = {actual:R} {baseKey} in the table, but the definition gives {expected:R} (relative error {relativeError:E2}).");
    }

    // ---- 2. internal consistency ---------------------------------------------------------------------------------

    [Fact]
    public void Ratios_are_reciprocal_for_every_pair_of_units()
    {
        UnitConverterDataLoader loader = LoadData();
        var problems = new List<string>();
        foreach (Category cat in loader.GetOrderedCategories().Where(c => c.Id != (int)ConverterCategory.Temperature))
        {
            List<Unit> units = loader.GetOrderedUnits(cat);
            foreach (Unit a in units)
            {
                Dictionary<Unit, ConversionData> fromA = loader.LoadOrderedRatios(a);
                foreach (Unit b in units)
                {
                    Dictionary<Unit, ConversionData> fromB = loader.LoadOrderedRatios(b);
                    if (!fromA.TryGetValue(b, out ConversionData ab) || !fromB.TryGetValue(a, out ConversionData ba))
                    {
                        problems.Add($"{cat.Name}: no ratio between {a.Name} and {b.Name}");
                        continue;
                    }

                    double product = ab.Ratio * ba.Ratio;
                    if (!(Math.Abs(product - 1.0) < 1e-12))
                    {
                        problems.Add($"{cat.Name}: {a.Name} to {b.Name} times back is {product:R}");
                    }
                }
            }
        }

        Assert.True(problems.Count == 0, string.Join(Environment.NewLine, problems.Take(10)));
    }

    [Fact]
    public void Ratios_are_transitive_inside_a_category()
    {
        UnitConverterDataLoader loader = LoadData();
        var problems = new List<string>();
        foreach (Category cat in loader.GetOrderedCategories().Where(c => c.Id != (int)ConverterCategory.Temperature))
        {
            List<Unit> units = loader.GetOrderedUnits(cat);
            Unit first = units[0];
            Unit second = units[units.Count / 2];
            foreach (Unit c in units)
            {
                // first -> second -> c must give the same as first -> c
                double direct = loader.LoadOrderedRatios(first)[c].Ratio;
                double viaSecond = loader.LoadOrderedRatios(first)[second].Ratio * loader.LoadOrderedRatios(second)[c].Ratio;
                if (Math.Abs(direct - viaSecond) > Math.Abs(direct) * 1e-12)
                {
                    problems.Add($"{cat.Name}: {first.Name} to {c.Name} is {direct:R} directly but {viaSecond:R} through {second.Name}");
                }
            }
        }

        Assert.True(problems.Count == 0, string.Join(Environment.NewLine, problems.Take(10)));
    }

    [Fact]
    public void Ordered_categories_list_matches_what_the_loader_builds()
    {
        // MainViewModel builds its navigation list from UnitConverterDataLoader.OrderedCategories (so that the converter
        // is only created when it is opened): the list must stay in sync with the categories the loader really builds.
        UnitConverterDataLoader loader = LoadData();
        Assert.Equal(
            UnitConverterDataLoader.OrderedCategories.Select(c => (int)c).ToArray(),
            loader.GetOrderedCategories().Select(c => c.Id).ToArray());
    }

    // ---- 3. what the user sees ---------------------------------------------------------------------------------

    public static IEnumerable<object[]> DisplayedConversions()
    {
        // category, from, to, typed digits, expected text in the "to" field
        yield return new object[] { ConverterCategory.Speed, "UnitName_MilesPerHour", "UnitName_KilometersPerHour", "100", "160.9344" };
        yield return new object[] { ConverterCategory.Speed, "UnitName_Knot", "UnitName_KilometersPerHour", "10", "18.52" };
        yield return new object[] { ConverterCategory.Pressure, "UnitName_Atmosphere", "UnitName_MillimeterOfMercury", "1", "760" };
        yield return new object[] { ConverterCategory.Pressure, "UnitName_Atmosphere", "UnitName_Bar", "1", "1.01325" };
        yield return new object[] { ConverterCategory.Length, "UnitName_Inch", "UnitName_Centimeter", "1", "2.54" };
        yield return new object[] { ConverterCategory.Length, "UnitName_Mile", "UnitName_Kilometer", "1", "1.609344" };
        yield return new object[] { ConverterCategory.Volume, "UnitName_GallonUS", "UnitName_Liter", "1", "3.785412" };
        yield return new object[] { ConverterCategory.Energy, "UnitName_Kilowatthour", "UnitName_Kilojoule", "1", "3600" };
        yield return new object[] { ConverterCategory.Energy, "UnitName_BritishThermalUnit", "UnitName_Joule", "1", "1055.056" };
        yield return new object[] { ConverterCategory.Weight, "UnitName_Pound", "UnitName_Kilogram", "1", "0.453592" };
        yield return new object[] { ConverterCategory.Weight, "UnitName_Ounce", "UnitName_Gram", "1", "28.34952" };
        yield return new object[] { ConverterCategory.Area, "UnitName_Acre", "UnitName_SquareMeter", "1", "4046.856" };
        yield return new object[] { ConverterCategory.Data, "UnitName_Gibibytes", "UnitName_Megabyte", "1", "1073.742" };
        yield return new object[] { ConverterCategory.Time, "UnitName_Day", "UnitName_Second", "1", "86400" };
        yield return new object[] { ConverterCategory.Power, "UnitName_Horsepower", "UnitName_Watt", "1", "745.6999" };
        yield return new object[] { ConverterCategory.Angle, "UnitName_Degree", "UnitName_Radian", "180", "3.141593" };

        // temperatures: offsets in both directions
        yield return new object[] { ConverterCategory.Temperature, "UnitName_DegreesCelsius", "UnitName_DegreesFahrenheit", "0", "32" };
        yield return new object[] { ConverterCategory.Temperature, "UnitName_DegreesCelsius", "UnitName_DegreesFahrenheit", "37", "98.6" };
        yield return new object[] { ConverterCategory.Temperature, "UnitName_DegreesCelsius", "UnitName_Kelvin", "0", "273.15" };
        yield return new object[] { ConverterCategory.Temperature, "UnitName_DegreesFahrenheit", "UnitName_DegreesCelsius", "212", "100" };
        yield return new object[] { ConverterCategory.Temperature, "UnitName_DegreesFahrenheit", "UnitName_Kelvin", "32", "273.15" };
        yield return new object[] { ConverterCategory.Temperature, "UnitName_Kelvin", "UnitName_DegreesCelsius", "0", "-273.15" };
        yield return new object[] { ConverterCategory.Temperature, "UnitName_Kelvin", "UnitName_DegreesFahrenheit", "0", "-459.67" };
    }

    [Theory]
    [MemberData(nameof(DisplayedConversions))]
    public void Displayed_conversion_is_correct(ConverterCategory category, string from, string to, string digits, string expected)
    {
        Assert.Equal(expected, Convert(category, from, to, digits));
    }

    // ---- 3b. the machine culture must never change a result -------------------------------------------------------
    // Several of the 60 languages use another minus sign (U+2212 in sv-SE, nb-NO, fi-FI...), other digits or another
    // decimal mark. Anything formatted or parsed without CultureInfo.InvariantCulture would break here.

    [Theory]
    [InlineData("fr-FR")]
    [InlineData("de-CH")]
    [InlineData("tr-TR")]
    [InlineData("sv-SE")]
    [InlineData("nb-NO")]
    [InlineData("ar-SA")]
    [InlineData("hi-IN")]
    [InlineData("th-TH")]
    public void Results_do_not_depend_on_the_culture_of_the_machine(string cultureName)
    {
        CultureInfo culture;
        try
        {
            culture = CultureInfo.GetCultureInfo(cultureName);
        }
        catch (CultureNotFoundException)
        {
            return; // invariant-globalization machine: nothing to check
        }

        CultureInfo oldCulture = CultureInfo.CurrentCulture;
        CultureInfo oldUiCulture = CultureInfo.CurrentUICulture;
        try
        {
            CultureInfo.CurrentCulture = culture;
            CultureInfo.CurrentUICulture = culture;

            Assert.Equal("0.3", new Calc(Calc.CalcKind.Scientific).Type("0.1+0.2=").Primary);
            Assert.Equal("1,234.75", new Calc(Calc.CalcKind.Scientific).Type("1234.5+0.25=").Primary);
            Assert.Equal("-5", new Calc(Calc.CalcKind.Scientific).Type("7n+2=").Primary);
            Assert.Equal("0.125", new Calc(Calc.CalcKind.Standard).Type("1/8=").Primary);
            Assert.Equal("212", Convert(ConverterCategory.Temperature, "UnitName_DegreesCelsius", "UnitName_DegreesFahrenheit", "100"));
            Assert.Equal("-273.15", Convert(ConverterCategory.Temperature, "UnitName_Kelvin", "UnitName_DegreesCelsius", "0"));
            Assert.Equal("2.54", Convert(ConverterCategory.Length, "UnitName_Inch", "UnitName_Centimeter", "1"));
        }
        finally
        {
            CultureInfo.CurrentCulture = oldCulture;
            CultureInfo.CurrentUICulture = oldUiCulture;
        }
    }
}
